use std::os::raw::c_void;
use std::ptr::null_mut;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use linux_kernel_module::{Module, NetfilterHook, NetfilterHookType};
use linux_kernel_module::netfilter::{NF_INET_LOCAL_IN, NF_INET_LOCAL_OUT};

struct Netfilter {
    hook: NetfilterHook,
    count: AtomicUsize,
}

impl Netfilter {
    fn new(hook: NetfilterHook) -> Self {
        Netfilter {
            hook,
            count: AtomicUsize::new(0),
        }
    }

    fn hook(&mut self, skb: *mut c_void, hook_type: NetfilterHookType) {
        self.count.fetch_add(1, Ordering::Relaxed);
        println!("Netfilter hook called! ({} times)", self.count.load(Ordering::Relaxed));
    }
}

#[no_mangle]
pub extern "C" fn netfilter_init() -> *mut c_void {
    let hook = NetfilterHook::new(NF_INET_LOCAL_IN);
    let netfilter = Arc::new(Netfilter::new(hook));
    netfilter.hook.register(netfilter.clone());
    netfilter.as_ptr() as *mut c_void
}

#[no_mangle]
pub extern "C" fn netfilter_exit(ptr: *mut c_void) {
    let netfilter = Arc::from_raw(ptr as *mut Netfilter);
    netfilter.hook.unregister();
}
```
